//! Expectations generated by executing the pinned VS Code sources and ripgrep.
//! Ordinary Rust tests need neither Node, network access nor ripgrep installed.
use crate::background::CancellationToken;
use crate::search_regex::SearchRegex;
use serde::Deserialize;

#[derive(Deserialize, Debug)]
#[serde(rename_all = "camelCase")]
struct Case {
    text: String,
    query: String,
    regex: bool,
    case_sensitive: bool,
    whole_word: bool,
    invalid: bool,
    matches: Vec<(usize, usize)>,
    selection: Option<(usize, usize, usize, usize)>,
}

#[derive(Deserialize, Debug)]
#[serde(rename_all = "camelCase")]
struct ReplacementCase {
    text: String,
    query: String,
    replacement: String,
    preserve: bool,
    editor_result: String,
    workspace_result: Option<String>,
}

#[derive(Deserialize)]
struct PreservedCase {
    original: String,
    replacement: String,
    expected: String,
}

#[derive(Deserialize, Debug)]
struct GlobCase {
    pattern: String,
    file: String,
    expected: bool,
}

#[derive(Deserialize)]
struct Fixtures {
    revision: String,
    editor: Vec<Case>,
    workspace: Vec<Case>,
    replacements: Vec<ReplacementCase>,
    preserved: Vec<PreservedCase>,
    globs: Vec<GlobCase>,
}

fn fixtures() -> &'static Fixtures {
    static FIXTURES: std::sync::OnceLock<Fixtures> = std::sync::OnceLock::new();
    FIXTURES.get_or_init(|| {
        serde_json::from_str(include_str!("../tests/fixtures/vscode-search.json")).unwrap()
    })
}

#[test]
fn vscode_editor_search_matches_upstream() {
    let fixtures = fixtures();
    assert_eq!(
        fixtures.revision,
        "959031245ebb1fe077e0d512e1397c0ae82006e4"
    );
    check_cases(&fixtures.editor, false);
}

#[test]
fn vscode_workspace_search_matches_ripgrep() {
    check_cases(&fixtures().workspace, true);
}

#[test]
fn vscode_search_globs_match_upstream() {
    for case in &fixtures().globs {
        assert_eq!(
            crate::search_paths::matches_glob(&case.file, &case.pattern),
            case.expected,
            "{case:?}"
        );
    }
}

fn check_cases(cases: &[Case], workspace: bool) {
    let cancel = CancellationToken::new();
    let mut failed = Vec::new();
    let mut count = 0;
    let mut patterns = std::collections::HashMap::<String, usize>::new();
    let mut workspace_patterns = std::collections::HashMap::new();
    let mut sources = std::collections::HashMap::new();
    let mut cases: Vec<_> = cases.iter().collect();
    if !workspace {
        // Every upstream input still goes through the real editor scan. Group
        // independent oracle cases so its bounded pattern cache can reuse a
        // configuration instead of repeatedly compiling it for other texts.
        cases.sort_by(|left, right| {
            (
                &left.query,
                left.case_sensitive,
                left.whole_word,
                left.regex,
            )
                .cmp(&(
                    &right.query,
                    right.case_sensitive,
                    right.whole_word,
                    right.regex,
                ))
        });
    }
    for case in cases {
        let rope = sources
            .entry(case.text.as_str())
            .or_insert_with(|| ropey::Rope::from_str(&case.text));
        let (ranges, invalid) = if workspace {
            if case.query.is_empty() {
                (Vec::new(), false)
            } else {
                let key = (
                    case.query.as_str(),
                    case.case_sensitive,
                    case.whole_word,
                    case.regex,
                );
                // Compile every distinct workspace configuration, including
                // invalid ones, once; all texts and selections are still scanned.
                match workspace_patterns.entry(key).or_insert_with(|| {
                    SearchRegex::workspace(
                        &case.query,
                        case.case_sensitive,
                        case.whole_word,
                        case.regex,
                    )
                }) {
                    Ok(regex) => (regex.scan(rope, case.selection, 19_999, &cancel).0, false),
                    Err(_) => (Vec::new(), true),
                }
            }
        } else {
            let (ranges, truncated, error) = crate::app_search_algo::scan_search_matches(
                rope,
                &case.query,
                case.case_sensitive,
                case.regex,
                case.whole_word,
                case.selection,
                &cancel,
            );
            assert!(!truncated);
            (ranges, error.is_some())
        };
        let actual = ranges
            .into_iter()
            .map(|(row, start, end)| {
                let offset = rope.line_to_char(row);
                (offset + start, offset + end)
            })
            .collect::<Vec<_>>();
        if actual != case.matches || invalid != case.invalid {
            count += 1;
            let shown = patterns.entry(case.query.clone()).or_default();
            if failed.len() < 40 && *shown < 2 {
                failed.push(format!("{case:?}\nactual={actual:?}, invalid={invalid}"));
                *shown += 1;
            }
        }
    }
    assert_eq!(count, 0, "{count} differences:\n{}", failed.join("\n"));
}

#[test]
fn vscode_editor_and_workspace_replacements_match_upstream() {
    let mut failures = Vec::new();
    let mut regexes = std::collections::HashMap::new();
    for case in &fixtures().replacements {
        let regex = regexes
            .entry(case.query.as_str())
            .or_insert_with(|| SearchRegex::new(&case.query, true, false).unwrap());
        let captures = regex.captures_at(&case.text, 0).unwrap();
        let pattern = crate::search_replace::Replacement::new(&case.replacement, true);
        let actual = pattern.expand(&case.text, &captures, case.preserve);
        if actual != case.editor_result {
            failures.push(format!("editor {case:?}: got {actual:?}"));
        }
        if let Some(expected) = &case.workspace_result {
            let actual = crate::search_replace::expand_workspace(
                &case.replacement,
                &case.text,
                &captures,
                case.preserve,
            );
            if &actual != expected {
                failures.push(format!("workspace {case:?}: got {actual:?}"));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} differences:\n{}",
        failures.len(),
        failures
            .iter()
            .take(20)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

#[test]
fn vscode_preserve_case_matches_upstream() {
    for case in &fixtures().preserved {
        assert_eq!(
            crate::search_replace::preserve_case(&case.original, &case.replacement),
            case.expected,
            "original={:?}, replacement={:?}",
            case.original,
            case.replacement
        );
    }
}
